                    "domain_en" => $base_en . " — " . $sf[0],
                    "domain_ar" => $base_ar . " — " . $sf[1],
                    "short_en" => $base_en,
                    "short_ar" => $base_ar,
                ];
            }
        }
    }
    return $data;
}

function get_all_1000_disciplines() {
